def bidi(p):p.alignment=WD_ALIGN_PARAGRAPH.RIGHT;p._p.get_or_add_pPr().append(OxmlElement('w:bidi'))
def run(p,t,size=10.5,b=False,c=INK):
 r=p.add_run(str(t));r.font.name=AR_FONT;r._element.rPr.rFonts.set(qn('w:cs'),AR_FONT);r.font.size=Pt(size);r.font.bold=b;r.font.color.rgb=RGBColor.from_string(c);return r
def para(d,t,style=None,size=10.5,b=False,c=INK):p=d.add_paragraph(style=style);bidi(p);run(p,t,size,b,c);return p
def bullets(d,xs):
 for x in xs:para(d,x,'List Bullet')
def shade(c,col):z=c._tc.get_or_add_tcPr();x=OxmlElement('w:shd');x.set(qn('w:fill'),col);z.append(x)
def table(d,h,rows,widths=None):
 t=d.add_table(rows=1,cols=len(h));t.style='Table Grid';t.alignment=WD_TABLE_ALIGNMENT.CENTER
 for j,x in enumerate(h):c=t.rows[0].cells[j];shade(c,NAVY);p=c.paragraphs[0];bidi(p);run(p,x,8.7,True,WHITE)
 for i,row in enumerate(rows):
  cells=t.add_row().cells
  for j,x in enumerate(row):
   c=cells[j];c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.TOP
   if i%2==0:shade(c,'F2F7F8')
   p=c.paragraphs[0];bidi(p);run(p,x,8.3)
   if widths:c.width=Inches(widths[j])
 return t
