 d=Document();s=d.styles;s['Normal'].font.name=AR_FONT;s['Normal']._element.rPr.rFonts.set(qn('w:cs'),AR_FONT);s['Normal'].font.size=Pt(10.5)
 for st,sz,col in [('Title',25,NAVY),('Heading 1',17,NAVY),('Heading 2',13,TEAL)]:s[st].font.name=AR_FONT;s[st]._element.rPr.rFonts.set(qn('w:cs'),AR_FONT);s[st].font.size=Pt(sz);s[st].font.color.rgb=RGBColor.from_string(col)
 sec=d.sections[0];sec.top_margin=Inches(.55);sec.bottom_margin=Inches(.55);sec.left_margin=Inches(.58);sec.right_margin=Inches(.58);p=d.add_paragraph();bidi(p);run(p,t,25,True,NAVY);p=d.add_paragraph();bidi(p);run(p,sub,12,False,TEAL);hp=sec.header.paragraphs[0];bidi(hp);run(hp,'تأسيس وعي المسلم المعاصر | الوحدة 6 v0.2',8,True,TEAL);fp=sec.footer.paragraphs[0];fp.alignment=WD_ALIGN_PARAGRAPH.CENTER;run(fp,'إصدار إنتاجي v0.2  •  25 أكتوبر 2026',8,False,MUTED);return d

